body.script:
(function () {
    // ── Lazy-load Cropper.js only when the user picks a photo ──
    var CROPPER_CSS = 'https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.6.2/cropper.min.css';
    var CROPPER_JS  = 'https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.6.2/cropper.min.js';
    var cropperLoaded = false;
    var cropperLoading = false;
    var pendingFile = null;

    function loadCropper(cb) {
        if (cropperLoaded) { cb(); return; }
        if (cropperLoading) { var t = setInterval(function(){ if(cropperLoaded){clearInterval(t);cb();} }, 50); return; }
        cropperLoading = true;
        var css = document.createElement('link');
        css.rel = 'stylesheet'; css.href = CROPPER_CSS; css.crossOrigin = 'anonymous';
        document.head.appendChild(css);
        var js = document.createElement('script');
        js.src = CROPPER_JS; js.crossOrigin = 'anonymous';
        js.onload = function () { cropperLoaded = true; cb(); };
        document.head.appendChild(js);
    }

    // ── Photo upload → cropper → replace file with cropped portrait ──
    var photoInput = document.getElementById('photoInput');
    var cropOverlay = document.getElementById('cropperModal');
    var cropImg = document.getElementById('cropperImage');
    var cropper = null;

    function setPhotoPreview(src) {
        var img = document.getElementById('photoPreview');
        var ph  = document.getElementById('avatarPlaceholder');
        var frame = document.querySelector('.reg-photo-frame');
        var clearBtn = document.getElementById('photoClearBtn');
        if (img) { img.src = src; img.style.display = 'block'; }
        if (ph)  { ph.style.display = 'none'; }
        if (frame) { frame.classList.add('has-photo'); }
        if (clearBtn) { clearBtn.classList.remove('is-hidden'); }
        var errMsg = document.getElementById('photoErrorMsg');
        if (errMsg) errMsg.remove();
    }

    function clearPhotoPreview() {
        var img = document.getElementById('photoPreview');
        var ph  = document.getElementById('avatarPlaceholder');
        var frame = document.querySelector('.reg-photo-frame');
        var clearBtn = document.getElementById('photoClearBtn');
        if (img) { img.src = ''; img.style.display = 'none'; }
        if (ph)  { ph.style.display = ''; }
        if (frame) { frame.classList.remove('has-photo'); }
        if (clearBtn) { clearBtn.classList.add('is-hidden'); }
        if (photoInput) { photoInput.value = ''; }
    }

    var photoClearBtn = document.getElementById('photoClearBtn');
    if (photoClearBtn) {
        photoClearBtn.addEventListener('click', function (e) {
            e.preventDefault();
            clearPhotoPreview();
        });
    }

    function closeCropper() {
        if (cropOverlay) cropOverlay.classList.remove('open');
        document.body.style.overflow = '';
        if (cropper) { cropper.destroy(); cropper = null; }
    }

    function openCropper(file) {
        var reader = new FileReader();
        reader.onload = function (e) {
            cropImg.src = e.target.result;
            cropOverlay.classList.add('open');
            document.body.style.overflow = 'hidden';
            if (cropper) cropper.destroy();
            cropper = new Cropper(cropImg, {
                aspectRatio: 4 / 5,
                viewMode: 1,
                autoCropArea: 1,
                dragMode: 'move',
                background: false,
                responsive: true,
                movable: true,
                zoomable: true,
                rotatable: true,
                scalable: false,
                minContainerHeight: 300
            });
        };
        reader.readAsDataURL(file);
    }

    if (photoInput) {
        photoInput.addEventListener('change', function () {
            var f = this.files && this.files[0];
            if (!f) return;
            if (!/^image\//.test(f.type)) {
                var reader = new FileReader();
                reader.onload = function (e) { setPhotoPreview(e.target.result); };
                reader.readAsDataURL(f);
                return;
            }
            // Load Cropper.js on demand, then open the cropper
            loadCropper(function () { openCropper(f); });
        });
    }

    // Cropper toolbar
    function bindTool(id, fn) {
        var el = document.getElementById(id);
        if (el) el.addEventListener('click', function () { if (cropper) fn(); });
    }
    bindTool('cropRotateL', function () { cropper.rotate(-90); });
    bindTool('cropRotateR', function () { cropper.rotate(90); });
    bindTool('cropZoomIn',  function () { cropper.zoom(0.1); });
    bindTool('cropZoomOut', function () { cropper.zoom(-0.1); });

    function cancelCrop() {
        if (photoInput) photoInput.value = '';
        closeCropper();
    }
    var cc1 = document.getElementById('cropCancel');
    var cc2 = document.getElementById('cropCancelBtn');
    if (cc1) cc1.addEventListener('click', cancelCrop);
    if (cc2) cc2.addEventListener('click', cancelCrop);
    if (cropOverlay) {
        cropOverlay.addEventListener('click', function (e) {
            if (e.target === cropOverlay) cancelCrop();
        });
    }

    var cropApply = document.getElementById('cropApply');
    if (cropApply) {
        cropApply.addEventListener('click', function () {
            if (!cropper) return;
            var canvas = cropper.getCroppedCanvas({
                width: 900, height: 1125,
                imageSmoothingEnabled: true,
                imageSmoothingQuality: 'high'
            });
            if (!canvas) { closeCropper(); return; }
            canvas.toBlob(function (blob) {
                if (!blob) { closeCropper(); return; }
                var base = (photoInput.files[0] && photoInput.files[0].name
                            ? photoInput.files[0].name.replace(/\.[^.]+$/, '') : 'photo');
                var cropped = new File([blob], base + '.jpg', { type: 'image/jpeg' });
                try {
                    var dt = new DataTransfer();
                    dt.items.add(cropped);
                    photoInput.files = dt.files;
                } catch (err) { /* older browser — original file stays */ }
                setPhotoPreview(canvas.toDataURL('image/jpeg', 0.92));
                closeCropper();
            }, 'image/jpeg', 0.92);
        });
    }

    // Payment receipt filename + required gate sync
    var paymentInput = document.getElementById('paymentInput');
    var paymentClearBtn = document.getElementById('paymentClearBtn');
    var paymentHintDefault = 'JPG · PNG · PDF \u00a0·\u00a0 Max 5 MB';

    function setPaymentProofUI(hasFile, fileName) {
        var hint = document.getElementById('paymentFileName');
        var icon = document.getElementById('paymentPreviewIcon');
        if (hasFile) {
            if (hint) {
                hint.textContent = '✓ ' + (fileName || 'Proof attached');
                hint.style.color = '#276749';
                hint.style.fontWeight = '600';
            }
            if (icon) { icon.textContent = '✅'; icon.style.background = '#f0fff4'; }
            if (paymentClearBtn) paymentClearBtn.classList.remove('is-hidden');
        } else {
            if (hint) {
                hint.textContent = paymentHintDefault;
                hint.style.color = '';
                hint.style.fontWeight = '';
            }
            if (icon) { icon.textContent = '📎'; icon.style.background = ''; }
            if (paymentClearBtn) paymentClearBtn.classList.add('is-hidden');
        }
    }

    function syncPaymentProofGate() {
        var gate = document.getElementById('paymentProofGate');
        var section = document.getElementById('paymentSection');
        var missed = document.getElementById('paymentMissedBanner');
        var err = document.getElementById('paymentErrorMsg');
        var mustNote = document.getElementById('paymentMustNote');
        var hasFile = !!(paymentInput && paymentInput.files && paymentInput.files[0]);
        if (gate) gate.value = hasFile ? 'ok' : '';
        if (mustNote) mustNote.style.display = hasFile ? 'none' : '';
        if (hasFile) {
            if (section) section.classList.remove('is-missing');
            if (missed) missed.style.display = 'none';
            if (err) err.style.display = 'none';
        }
    }

    function clearPaymentProof() {
        if (paymentInput) paymentInput.value = '';
        setPaymentProofUI(false);
        syncPaymentProofGate();
    }

    if (paymentClearBtn) {
        paymentClearBtn.addEventListener('click', function (e) {
            e.preventDefault();
            clearPaymentProof();
        });
    }
    if (paymentInput) {
        paymentInput.addEventListener('change', function () {
            var file = this.files && this.files[0];
            setPaymentProofUI(!!file, file ? file.name : '');
            syncPaymentProofGate();
        });
        syncPaymentProofGate();
    }

    // Jersey name → uppercase
    var jName = document.getElementById('jerseyName');
    if (jName) {
        jName.addEventListener('input', function () {
            var p = this.selectionStart;
            this.value = this.value.toUpperCase();
            this.setSelectionRange(p, p);
        });
    }

    // ── Secure Registration → scroll to form start ───────────────────
    var secureRegBtn = document.getElementById('reg-secure-registration-btn');
    if (secureRegBtn) {
        secureRegBtn.addEventListener('click', function (e) {
            var target = document.getElementById('reg-form-start');
            if (!target) return;
            e.preventDefault();
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            var firstSec = target.querySelector('.reg-section');
            if (firstSec) firstSec.classList.add('mob-open');
        });
    }

    // ── Mobile Accordion (≤ 640 px) ───────────────────────────────────
    if (window.innerWidth <= 640) {
        var sections = document.querySelectorAll('.reg-section');

        sections.forEach(function (sec, idx) {
            var header = sec.querySelector('.reg-section-header');
            if (!header) return;

            // Move all children after the header into a body wrapper
            var body = document.createElement('div');
            body.className = 'reg-section-body';
            var kids = Array.from(sec.children);
            kids.forEach(function (child) {
                if (child !== header) body.appendChild(child);
            });
            sec.appendChild(body);

            // Inject status dot + chevron into header
            var dot = document.createElement('span');
            dot.className = 'reg-mob-dot';

            var ns = 'http://www.w3.org/2000/svg';
            var svg = document.createElementNS(ns, 'svg');
            svg.setAttribute('class', 'reg-chevron');
            svg.setAttribute('viewBox', '0 0 24 24');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', 'currentColor');
            svg.setAttribute('stroke-width', '2.5');
            svg.setAttribute('stroke-linecap', 'round');
            svg.setAttribute('stroke-linejoin', 'round');
            var pl = document.createElementNS(ns, 'polyline');
            pl.setAttribute('points', '6 9 12 15 18 9');
            svg.appendChild(pl);

            header.appendChild(dot);
            header.appendChild(svg);

            // First section starts open
            if (idx === 0) sec.classList.add('mob-open');

            // Toggle on tap
            header.addEventListener('click', function () {
                sec.classList.toggle('mob-open');
            });
        });

        // Filled-state indicator — lights the dot when section has input
        function checkFilled() {
            document.querySelectorAll('.reg-section').forEach(function (sec) {
                var texts   = sec.querySelectorAll('input[type=text], input[type=tel], textarea');
                var selects = sec.querySelectorAll('select');
                var radios  = sec.querySelectorAll('input[type=radio]:checked');
                var files   = sec.querySelectorAll('input[type=file]');
                var filled  = false;
                texts.forEach(function (i)   { if (i.value.trim()) filled = true; });
                selects.forEach(function (s) { if (s.value)        filled = true; });
                if (radios.length)                                   filled = true;
                files.forEach(function (f)   { if (f.files && f.files[0]) filled = true; });
                sec.classList.toggle('mob-filled', filled);
            });
        }

        var formEl = document.querySelector('form');
        if (formEl) {
            formEl.addEventListener('input',  checkFilled);
            formEl.addEventListener('change', checkFilled);
        }
        checkFilled();
    }

    // Native HTML5 validation + top warning for mandatory fields
    var form = document.querySelector('form');
    if (form) {
        function showRegTopWarning(message, focusEl) {
            var alertBox = document.getElementById('regClientAlert');
            var alertMsg = document.getElementById('regClientAlertMsg');
            if (alertMsg) alertMsg.textContent = message || 'Please fill all mandatory fields marked with *.';
            if (alertBox) {
                alertBox.style.display = 'flex';
                try {
                    alertBox.scrollIntoView({ behavior: 'smooth', block: 'start' });
                } catch (err) {
                    alertBox.scrollIntoView(true);
                }
            }
            if (focusEl) {
                var parentSec = focusEl.closest ? focusEl.closest('.reg-section') : null;
                if (parentSec) parentSec.classList.add('mob-open');
                setTimeout(function () {
                    try {
                        focusEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    } catch (err2) {}
                    if (focusEl.classList) focusEl.classList.add('was-invalid');
                }, 320);
            }
        }
        function hideRegTopWarning() {
            var alertBox = document.getElementById('regClientAlert');
            if (alertBox) alertBox.style.display = 'none';
        }
        function markPaymentMissing() {
            var section = document.getElementById('paymentSection');
            var box = document.getElementById('paymentUploadBox');
            var missed = document.getElementById('paymentMissedBanner');
            var err = document.getElementById('paymentErrorMsg');
            if (section) {
                section.classList.add('is-missing', 'mob-open');
            }
            if (missed) missed.style.display = 'block';
            if (err) err.style.display = 'block';
            if (box) {
                box.style.transition = 'outline .15s';
                box.style.outline = '2px solid #e94560';
                box.style.borderRadius = '12px';
                setTimeout(function () { box.style.outline = ''; }, 4000);
            }
            showRegTopWarning(
                'Payment proof is required. Please upload a receipt or screenshot in the Payment Proof section.',
                section || box || document.getElementById('paymentFileBtn')
            );
        }
        function clearPaymentMissing() {
            var section = document.getElementById('paymentSection');
            var missed = document.getElementById('paymentMissedBanner');
            var err = document.getElementById('paymentErrorMsg');
            if (section) section.classList.remove('is-missing');
            if (missed) missed.style.display = 'none';
            if (err) err.style.display = 'none';
        }
        function isPaymentProofRequired() {
            var section = document.getElementById('paymentSection');
            var paymentInput = document.getElementById('paymentInput');
            var gate = document.getElementById('paymentProofGate');
            return form.getAttribute('data-payment-required') === '1'
                || (section && section.getAttribute('data-payment-required') === '1')
                || (paymentInput && paymentInput.getAttribute('data-required') === '1')
                || !!gate;
        }
        function hasPaymentProofFile() {
            var paymentInput = document.getElementById('paymentInput');
            return !!(paymentInput && paymentInput.files && paymentInput.files[0]);
        }

        form.addEventListener('submit', function (e) {
            hideRegTopWarning();

            // Keep gate in sync before validating
            var gate = document.getElementById('paymentProofGate');
            if (gate) gate.value = hasPaymentProofFile() ? 'ok' : '';

            // Photo is mandatory — check before native validation
            var photoInput = document.getElementById('photoInput');
            var photoSection = document.getElementById('photoSection');
            if (photoInput && (!photoInput.files || !photoInput.files[0])) {
                e.preventDefault();
                e.stopPropagation();
                if (photoSection) {
                    photoSection.style.transition = 'outline .15s';
                    photoSection.style.outline = '2px solid #e94560';
                    photoSection.style.borderRadius = '10px';
                    photoSection.style.padding = '8px';
                    setTimeout(function () { photoSection.style.outline = ''; photoSection.style.padding = ''; }, 3000);
                }
                var errId = 'photoErrorMsg';
                var existing = document.getElementById(errId);
                if (!existing) {
                    var msg = document.createElement('p');
                    msg.id = errId;
                    msg.textContent = '⚠️ Player photo is required. Please upload a photo before submitting.';
                    msg.style.cssText = 'color:#e94560;font-size:.8rem;font-weight:600;margin-top:.4rem;';
                    if (photoSection) photoSection.appendChild(msg);
                }
                showRegTopWarning('Player photo is required. Please upload a photo before submitting.', photoSection || photoInput);
                return;
            }
            var errMsg = document.getElementById('photoErrorMsg');
            if (errMsg) errMsg.remove();

            // Payment proof — mandatory only when tournament requires it
            if (isPaymentProofRequired() && !hasPaymentProofFile()) {
                e.preventDefault();
                e.stopPropagation();
                markPaymentMissing();
                return;
            }
            clearPaymentMissing();

            if (!form.checkValidity()) {
                e.preventDefault();
                e.stopPropagation();
                var first = form.querySelector(':invalid');
                var labelText = 'Please fill all mandatory fields marked with *.';
                if (first) {
                    if (first.id === 'paymentProofGate' || first.name === 'payment_proof_gate' || first.name === 'payment_proof') {
                        markPaymentMissing();
                        return;
                    }
                    if (first.id === 'jerseySize' || first.name === 'jersy_size') {
                        labelText = 'Jersey size is required. Please select a jersey size.';
                    } else {
                    var lbl = form.querySelector('label[for="' + (first.id || '') + '"]');
                    if (lbl) {
                        var raw = (lbl.textContent || '').replace(/\*/g, '').replace(/\(optional\)/ig, '').trim();
                        if (raw) labelText = raw + ' is required. Please complete this field.';
                    } else if (first.name === 'role') {
                        labelText = 'Role is required. Please select a role.';
                    } else if (first.name) {
                        labelText = 'Please complete the required field: ' + first.name.replace(/_/g, ' ') + '.';
                    }
                    }
                    var parentSec = first.closest('.reg-section');
                    if (parentSec) parentSec.classList.add('mob-open');
                    first.classList.add('was-invalid');
                }
                showRegTopWarning(labelText, first);
            }
        });
    }
})();

// ── Card preview: dynamic scale; scaler shrink-wraps so card stays centered ─
(function () {
    var wrap   = document.querySelector('.reg-card-preview-wrap');
    var scaler = document.querySelector('.reg-card-preview-scaler');
    var frame  = document.querySelector('.reg-card-preview-frame');
    if (!scaler || !frame) return;

    var CARD_W = 832;
    var CARD_H = 421;
    var MAX_H  = 220;   // max displayed height — keeps preview compact

    function fitCard() {
        var availW = (wrap && wrap.clientWidth) ? wrap.clientWidth : scaler.parentElement.clientWidth;
        var scale  = Math.min(availW / CARD_W, MAX_H / CARD_H);
        var dispW  = Math.round(CARD_W * scale);
        var dispH  = Math.round(CARD_H * scale);
        frame.style.transformOrigin = 'top left';
        frame.style.transform = 'scale(' + scale + ')';
        scaler.style.width  = dispW + 'px';
        scaler.style.height = dispH + 'px';
    }

    fitCard();
    frame.addEventListener('load', fitCard);
    window.addEventListener('resize', fitCard);
})();

// ── Cricket role → batting/bowling style logic ───────────────────────────
(function () {
    var battEl = document.getElementById('battingStyle');
    var bowlEl = document.getElementById('bowlingStyle');
    if (!battEl || !bowlEl) return;

    // Track which fields were auto-set (not manually chosen by user)
    var autoSet = { batting: false, bowling: false };

    var battNaOpt = battEl.querySelector('option[value="NA"]');
    var bowlNaOpt = bowlEl.querySelector('option[value="NA"]');

    function showNaOptions(show) {
        if (battNaOpt) battNaOpt.style.display = show ? '' : 'none';
        if (bowlNaOpt) bowlNaOpt.style.display = show ? '' : 'none';
    }

    function applyRole(role) {
        if (role === 'Batter') {
            showNaOptions(true);
            // Auto-set bowling to NA; clear if it was previously auto-set
            if (autoSet.batting) { battEl.value = ''; autoSet.batting = false; }
            bowlEl.value = 'NA'; autoSet.bowling = true;
        } else if (role === 'Bowler') {
            showNaOptions(true);
            // Auto-set batting to NA; clear bowling if it was previously auto-set
            battEl.value = 'NA'; autoSet.batting = true;
            if (autoSet.bowling) { bowlEl.value = ''; autoSet.bowling = false; }
        } else if (role === 'Allrounder') {
            // Reset any auto-set NA fields, then hide NA option
            if (autoSet.batting) { battEl.value = ''; autoSet.batting = false; }
            if (autoSet.bowling) { bowlEl.value = ''; autoSet.bowling = false; }
            showNaOptions(false);
        }
    }

    // Clear auto-set flag when user manually picks a value
    battEl.addEventListener('change', function () { autoSet.batting = false; });
    bowlEl.addEventListener('change', function () { autoSet.bowling = false; });

    document.querySelectorAll('input[name="role"]').forEach(function (radio) {
        radio.addEventListener('change', function () {
            if (this.checked) applyRole(this.value);
        });
    });

    // Apply on page load if a role is pre-checked
    var checked = document.querySelector('input[name="role"]:checked');
    if (checked) applyRole(checked.value);
    else showNaOptions(false); // hide NA until a role is picked
})();
(function () {
    var codeEl   = document.getElementById('countryCode');
    var numEl    = document.getElementById('mobileNumber');
    var fullEl   = document.getElementById('contactFull');
    var warnEl   = document.getElementById('mobileWarning');
    var hintEl   = document.getElementById('mobileHint');
    if (!codeEl || !numEl || !fullEl) return;

    function selectedOption() {
        return codeEl.options[codeEl.selectedIndex] || null;
    }

    function digitRules() {
        var opt = selectedOption();
        var min = parseInt(opt && opt.getAttribute('data-min'), 10);
        var max = parseInt(opt && opt.getAttribute('data-max'), 10);
        if (!(min > 0)) min = 10;
        if (!(max > 0)) max = min;
        if (max < min) max = min;
        return {
            min: min,
            max: max,
            placeholder: (opt && opt.getAttribute('data-placeholder')) || '',
        };
    }

    function isCompleteLength(len) {
        var rules = digitRules();
        return len >= rules.min && len <= rules.max;
    }

    function applyCountryRules() {
        var rules = digitRules();
        var digits = (numEl.value || '').replace(/\D/g, '');
        if (digits.length > rules.max) {
            digits = digits.slice(0, rules.max);
        }
        numEl.value = digits;
        numEl.setAttribute('maxlength', String(rules.max));
        if (rules.min === rules.max) {
            numEl.setAttribute('pattern', '[0-9]{' + rules.min + '}');
            numEl.setAttribute('title', 'Enter ' + rules.min + ' digits for the selected country');
            if (hintEl) {
                hintEl.textContent = 'Enter ' + rules.min + ' digits (without country code)';
            }
        } else {
            numEl.setAttribute('pattern', '[0-9]{' + rules.min + ',' + rules.max + '}');
            numEl.setAttribute('title',
                'Enter ' + rules.min + '–' + rules.max + ' digits for the selected country');
            if (hintEl) {
                hintEl.textContent =
                    'Enter ' + rules.min + '–' + rules.max + ' digits (without country code)';
            }
        }
        if (rules.placeholder) {
            numEl.setAttribute('placeholder', rules.placeholder);
        }
        syncFull();
    }

    // Enforce digits-only input within the active country length
    numEl.addEventListener('input', function () {
        var rules = digitRules();
        var v = this.value.replace(/\D/g, '');
        if (v.length > rules.max) v = v.slice(0, rules.max);
        this.value = v;
        syncFull();
    });

    // Sync hidden field whenever code or number changes
    codeEl.addEventListener('change', function () {
        applyCountryRules();
        checkDuplicate();
    });

    function syncFull() {
        var num = numEl.value.trim();
        fullEl.value = num ? (codeEl.value + num) : '';
    }

    // Required validation on the visible input
    numEl.setAttribute('required', 'required');

    // Check duplicate on blur when national number length is complete
    numEl.addEventListener('blur', function () {
        syncFull();
        if (isCompleteLength(numEl.value.length)) checkDuplicate();
    });

    function checkDuplicate() {
        var num = numEl.value.trim();
        if (!isCompleteLength(num.length)) { hideDupWarn(); return; }
        var mobile = codeEl.value + num;
        // Read db_name and tournament_slug from the form's action URL
        var form   = document.querySelector('form');
        if (!form) return;
        var parts  = (form.getAttribute('action') || window.location.pathname).split('/');
        // URL pattern: /db_name/slug/player/register
        var regIdx = parts.indexOf('player');
        if (regIdx < 2) return;
        var dbName  = parts[regIdx - 2];
        var slug    = parts[regIdx - 1];
        var url     = '/' + dbName + '/' + slug + '/player/check_mobile';
        fetch(url, {
            method:  'POST',
            headers: { 'Content-Type': 'application/json' },
            body:    JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1,
                                      params: { mobile: mobile } })
        })
        .then(function (r) { return r.json(); })
        .then(function (data) {
            var result = data && data.result;
            if (result && result.duplicate) showDupWarn();
            else hideDupWarn();
        })
        .catch(function () { hideDupWarn(); });
    }

    function showDupWarn() { if (warnEl) warnEl.style.display = 'block'; }
    function hideDupWarn() { if (warnEl) warnEl.style.display = 'none';  }

    // On form submit — sync combined value (HTML pattern uses active country length)
    var form = document.querySelector('form');
    if (form) {
        form.addEventListener('submit', function () { syncFull(); }, true);
    }

    applyCountryRules();
})();
